function cmap = fmri_makecmap(colors, positions, n)
% FMRI_MAKECMAP  Builds a colormap from anchor colours and their positions.
%
% Creates a colormap from two or more anchor colours. Each anchor sets the
% exact colour at a specified position in the colormap, and the colours
% between anchors are generated by linear interpolation. Moving an anchor
% changes where its colour appears and how much of the colormap is used for
% the transitions to the neighbouring colours.
%
% Usage:
%   cmap = fmri_makecmap(colors)                       % evenly spaced anchors
%   cmap = fmri_makecmap(colors, positions)
%   cmap = fmri_makecmap(colors, positions, n)
%
% Inputs:
%   COLORS    - K x 3 matrix of anchor colours in [0, 1], ordered from the low
%               end of the colour range to the high end.
%   POSITIONS - K-element vector specifying where each anchor colour appears
%               in the colormap. Values must be strictly increasing and are
%               rescaled internally to span the full colormap. The spacing
%               between positions controls the length of each colour
%               transition. For example, with three colours, [1 20 100]
%               places the middle colour near the low end, while [1 50 100]
%               places it at the centre. Default: evenly spaced.
%   N         - Number of colours in the result. Default 256.
%
% Outputs:
%   CMAP      - N x 3 colormap, ready to pass to any of the display functions.
%
% WHY THIS IS A SEPARATE FUNCTION
%   Colormap construction and data display are handled separately. This
%   function creates a non-uniform N x 3 colormap that can be passed to any
%   toolbox viewer, without requiring additional colour-scaling arguments in
%   each display function.
%
% Examples:
%   % Even blue-grey-red, the toolbox default shape
%   cmap = fmri_makecmap([0 0 0.8; 0.7 0.7 0.7; 1 0 0]);
%
%   % Same colours, but blue gives way to grey quickly and grey to red slowly.
%   % Useful when negative values are few and should stay saturated.
%   cmap = fmri_makecmap([0 0 0.8; 0.7 0.7 0.7; 1 0 0], [1 20 100]);
%
%   % Five anchors, evenly spaced
%   cmap = fmri_makecmap([0 0 1; 0.5 0.7 1; 1 1 1; 1 0.6 0.5; 1 0 0]);
%
%   % Use with any viewer
%   fmri_showslices(t_map, 1, 2, [-8 8], [], [], 1, cmap, 4.14);
%
% See also: fmri_divmap, fmri_showslices, fmri_showselectslices, fmri_showcortex,
%           fmri_braincake, fmri_colorbar

if nargin < 2, positions = []; end
if nargin < 3 || isempty(n), n = 256; end

if ~isnumeric(colors) || size(colors, 2) ~= 3 || size(colors, 1) < 2
    error('fmri_makecmap:badColors', ...
        ['COLORS must be a K x 3 matrix with at least two rows.\n' ...
         'Got %s.'], mat2str(size(colors)));
end
if any(colors(:) < 0) || any(colors(:) > 1)
    error('fmri_makecmap:colorRange', ...
        ['COLORS must be in [0, 1]. Got values from %g to %g.\n' ...
         'If these are 0-255 values, divide by 255.'], min(colors(:)), max(colors(:)));
end

K = size(colors, 1);
if isempty(positions)
    positions = linspace(0, 1, K);
end
positions = positions(:)';
if numel(positions) ~= K
    error('fmri_makecmap:lengthMismatch', ...
        ['POSITIONS must have one entry per anchor colour: %d colours but %d ' ...
         'positions.'], K, numel(positions));
end
if any(diff(positions) <= 0)
    error('fmri_makecmap:notIncreasing', ...
        ['POSITIONS must be strictly increasing, got %s.\n' ...
         'Two anchors at the same position would make the transition ' ...
         'undefined.'], mat2str(positions));
end
if ~isscalar(n) || n < 2
    error('fmri_makecmap:badN', 'N must be a scalar of at least 2, got %s.', mat2str(n));
end

% Rescale positions to [0, 1] so that any convention works - [1 50 100],
% [0 0.5 1] and [1 10 100] all describe the same shape at different scales.
positions = (positions - positions(1)) / (positions(end) - positions(1));

q = linspace(0, 1, round(n))';
cmap = [interp1(positions, colors(:,1), q, 'linear'), ...
        interp1(positions, colors(:,2), q, 'linear'), ...
        interp1(positions, colors(:,3), q, 'linear')];
cmap = min(max(cmap, 0), 1);
end